import sys
from math import gcd

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        q = int(next(iterator))
    except StopIteration:
        return

    a = []

    results = []

    for _ in range(q):
        t = int(next(iterator))
        if t == 1:
            u = int(next(iterator))
            a.append(u)
        else:
            x = int(next(iterator))
            k = int(next(iterator))
            s = int(next(iterator))

            best_v = -1
            best_xor = -1

            for v in a:
                g = gcd(x, v)
                if k % g != 0:
                    continue
                if x + v > s:
                    continue

                current_xor = x ^ v
                if current_xor > best_xor:
                    best_xor = current_xor
                    best_v = v
                elif current_xor == best_xor:
                    if v > best_v:
                        best_v = v

            results.append(str(best_v))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == '__main__':
    solve()
